import { describe, expect, it } from 'vitest'
import { readCloudSessionTag, withCloudSessionMarker } from './cloud-session-marker'

const opened =
  'Fixes the hook.\n\nCloses #314\n\n---\n_Generated by [Claude Code](https://claude.ai/code/session_01AB)_\n'

describe('cloud session marker', () => {
  it('reads an unclaimed PR from its footer, then the claiming host from its marker', () => {
    expect(readCloudSessionTag(opened)).toEqual({ sessionId: 'session_01AB', host: null })
    const claimed = withCloudSessionMarker(opened, { sessionId: 'session_01AB', host: 'host-1' })
    expect(claimed).toBe(
      'Fixes the hook.\n\nCloses #314\n\n<!-- corka-cloud session=session_01AB host=host-1 -->\n'
    )
    expect(readCloudSessionTag(claimed)).toEqual({ sessionId: 'session_01AB', host: 'host-1' })
  })

  it('moves a PR to another host without stacking markers', () => {
    const first = withCloudSessionMarker(opened, { sessionId: 'session_01AB', host: 'host-1' })
    expect(withCloudSessionMarker(first, { sessionId: 'session_01AB', host: 'host-2' })).toBe(
      'Fixes the hook.\n\nCloses #314\n\n<!-- corka-cloud session=session_01AB host=host-2 -->\n'
    )
  })

  it('finds no session in a PR a person opened', () => {
    expect(readCloudSessionTag('## Summary\nDone.\n\nCloses #12')).toBeNull()
  })
})
